def _learned_as_runtime_capability(
    learned: learned_registry.LearnedCapability,
) -> RepairCapability:
    def builder(
        _incident: Any,
        _context: dict[str, Any],
    ) -> dict[str, Any]:
        return learned_registry.recipe_from_learned(
            learned
        )

    return RepairCapability(
        code=learned.code,
        incident_ids=learned.incident_ids,
        required_paths=learned.required_paths,
        builder=builder,
    )


def _resolve_capability(
    incident_id: str,
    capability_code: str | None,
    *,
    problem_signature: str | None = None,
) -> RepairCapability:
    code = str(capability_code or "").strip()

    if code:
        capability = _CAPABILITIES.get(code)

        if capability is not None:
            if incident_id not in capability.incident_ids:
                raise ValueError(
                    "REPAIR_CAPABILITY_INCIDENT_MISMATCH"
                )
            return capability

        learned = learned_registry.resolve_learned_capability(
            incident_id=incident_id,
            problem_signature=problem_signature,
            capability_code=code,
        )
        if learned is None:
            raise ValueError(
                "REPAIR_CAPABILITY_UNKNOWN"
            )
        return _learned_as_runtime_capability(
            learned
        )

    matches = [
        item
        for item in _CAPABILITIES.values()
        if incident_id in item.incident_ids
    ]

    learned = learned_registry.resolve_learned_capability(
        incident_id=incident_id,
        problem_signature=problem_signature,
    )

    if learned is not None:
        matches.append(
            _learned_as_runtime_capability(
                learned
            )
        )

    if not matches:
        raise ValueError(
            "REPAIR_CAPABILITY_UNKNOWN"
        )

    if len(matches) != 1:
        raise ValueError(
            "REPAIR_CAPABILITY_AMBIGUOUS"
        )

    return matches[0]


def _validate_scope(
    incident: Any,
    capability: RepairCapability,
    actions: list[dict[str, Any]],
) -> None:
    authorized = set(
        incident.target_paths
    )

    required = set(
        capability.required_paths
    )

    if not required.issubset(
        authorized
    ):
        raise ValueError(
            "REPAIR_CAPABILITY_SCOPE_NOT_AUTHORIZED"
        )

    action_paths = set()

    for action in actions:
        if not isinstance(
            action,
            dict,
        ):
            raise ValueError(
                "REPAIR_ACTION_INVALID"
            )

        path = str(
            action.get("path") or ""
        ).strip()

        if not path:
            raise ValueError(
                "REPAIR_ACTION_PATH_REQUIRED"
            )

        action_paths.add(path)

    if not action_paths:
        raise ValueError(
            "REPAIR_ACTION_SCOPE_EMPTY"
        )

    if not action_paths.issubset(
        authorized
    ):
        raise ValueError(
            "REPAIR_ACTION_SCOPE_MISMATCH"
        )


def _persist_spec(
    job: dict[str, Any],
) -> Path:
    REPAIR_SPECS.mkdir(
        parents=True,
        exist_ok=True,
    )

    path = (
        REPAIR_SPECS
        / f"{job['job_id']}.json"
    )

    serialized = (
        json.dumps(
            job,
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
        )
        + "\n"
    )

    if path.is_file():
        existing = path.read_text(
            encoding="utf-8"
        )

        if existing != serialized:
            raise ValueError(
                "REPAIR_SPEC_IDEMPOTENCY_CONFLICT"
            )

        return path

    with tempfile.NamedTemporaryFile(
        "w",
        encoding="utf-8",
        dir=REPAIR_SPECS,
        delete=False,
    ) as handle:
        handle.write(serialized)
        handle.flush()
        os.fsync(handle.fileno())
        temporary = Path(
            handle.name
        )

    os.replace(
        temporary,
        path,
    )

    return path


def build_deterministic_repair_job(
    incident_id: str,
    *,
    capability_code: str | None = None,
    problem_signature: str | None = None,
    requester: dict[str, Any] | None = None,
) -> dict[str, Any]:
    incident = (
        maintenance.read_runtime_incident(
            incident_id
        )
    )

    if incident is None:
        raise ValueError(
            "INCIDENT_NOT_DECLARED"
        )

    if incident.state not in {
        "REPAIR_REQUIRED",
        "REJECTED",
    }:
        raise ValueError(
            "INCIDENT_NOT_REPAIRABLE"
        )

    capability = (
        _resolve_capability(
            incident_id,
            capability_code,
            problem_signature=problem_signature,
        )
    )

    allowed, reason = (
        maintenance.repair_attempt_allowed(
            incident_id
        )
    )

    if (
        not allowed
        and not incident.repair_job_id
    ):
        raise ValueError(reason)

    provisional_job_id = (
        incident.repair_job_id
        or deterministic_repair_job_id(
            incident.incident_id,
            incident.attempts + 1,
        )
    )

    convergence = ensure_submit_convergence(
        ROOT,
        job_id=provisional_job_id,
        owner="worker-repair-planner",
        owner_pid=os.getpid(),
    )

    if (
        convergence.get("converged")
        is not True
    ):
        raise ValueError(
            "DEV_MIRROR_NOT_CONVERGED:"
            + str(convergence.get("status"))
        )

    context = {
        "base_sha": convergence[
            "development"
        ],
        "requester": (
            _canonical_requester(requester)
        ),
    }

    recipe = capability.builder(
        incident,
        context,
    )

    if not isinstance(
        recipe,
        dict,
    ):
        raise ValueError(
            "REPAIR_RECIPE_INVALID"
        )

    actions = recipe.get(
        "actions"
    )

    checks = recipe.get(
        "checks"
    )

    if not isinstance(
        actions,
        list,
    ):
        raise ValueError(
            "REPAIR_RECIPE_ACTIONS_INVALID"
        )

    if not isinstance(
        checks,
        list,
    ) or not checks:
        raise ValueError(
            "REPAIR_RECIPE_CHECKS_INVALID"
        )

    _validate_scope(
        incident,
        capability,
        actions,
    )

    attempt_number = (
        incident.attempts + 1
    )

    job_id = (
        incident.repair_job_id
        or deterministic_repair_job_id(
            incident.incident_id,
            attempt_number,
        )
    )

    job = canonicalize_job(
        {
            "job_id": job_id,
            "objective": str(
                recipe.get(
                    "objective"
                )
                or (
                    "Reparacion "
                    f"{capability.code}"
                )
            ),
            "mode": "MUTATION",
            "base_sha": context[
                "base_sha"
            ],
            "requester": context[
                "requester"
            ],
            "actions": actions,
            "checks": checks,
        }
    )

    errors = validate_worker_job(
        job
    )

    if errors:
        raise ValueError(
            "REPAIR_JOB_INVALID:"
            + ",".join(errors)
        )

    job = validate_repair_worker_job(
        incident_id,
        job,
    )

    spec = _persist_spec(
        job
    )

    return {
        "incident_id": incident_id,
        "capability": capability.code,
        "job": job,
        "spec_path": str(spec),
        "production_touched": False,
    }


def publish_planned_repair(
    incident_id: str,
    *,
    capability_code: str | None = None,
    problem_signature: str | None = None,
    requester: dict[str, Any] | None = None,
) -> dict[str, Any]:
    planned = (
        build_deterministic_repair_job(
            incident_id,
            capability_code=(
                capability_code
            ),
            problem_signature=(
                problem_signature
            ),
            requester=requester,
        )
    )

    publication = (
        publish_repair_job(
            incident_id,
            planned["job"],
        )
    )

    return {
        **planned,
        "publication": publication,
        "production_touched": False,
    }


