def _submit_local_lifecycle(
    job_id: str,
) -> str | None:

    name = f"{job_id}.json"

    if (
        (RESULTS / name).is_file()
        or (DONE / name).is_file()
    ):
        return "ALREADY_COMPLETED"

    if (PROCESSING / name).is_file():
        return "ALREADY_PROCESSING"

    if (PENDING / name).is_file():
        return "ALREADY_SUBMITTED"

    if (REJECTED / name).is_file():
        return "INVALID_JOB"

    return None


def _submit_remote_exists(
    job_id: str,
    *,
    remote: str,
    queue_branch: str,
) -> bool:

    rel = (
        "worker_queue/inbox/"
        f"{job_id}.json"
    )

    fetched = git(
        "fetch",
        remote,
        queue_branch,
        check=False,
    )

    if fetched.returncode != 0:
        return False

    return (
        git(
            "cat-file",
            "-e",
            f"{remote}/{queue_branch}:{rel}",
            check=False,
        ).returncode
        == 0
    )


def _submit_convergence(
    *,
    remote: str,
) -> dict[str, Any]:

    for branch in (
        "Edarsahub_Desarrollo",
        "mirror/emergent-live",
    ):
        fetched = git(
            "fetch",
            remote,
            branch,
            check=False,
        )

        if fetched.returncode != 0:
            return {
                "converged": False,
                "reason": "FETCH_FAILED",
            }

    local = git(
        "rev-parse",
        "HEAD",
        check=False,
    ).stdout.strip()

    development = git(
        "rev-parse",
        f"{remote}/Edarsahub_Desarrollo",
        check=False,
    ).stdout.strip()

    mirror = git(
        "rev-parse",
        f"{remote}/mirror/emergent-live",
        check=False,
    ).stdout.strip()

    return {
        "local": local,
        "development": development,
        "mirror": mirror,
        "converged": bool(
            local
            and local
            == development
            == mirror
        ),
    }


def _submit_failure_status(
    error: Exception,
) -> str:

    message = (
        f"{type(error).__name__}:{error}"
    ).upper()

    if (
        "REMOTE_MOVED_RETRY_REQUIRED"
        in message
    ):
        return "REMOTE_MOVED_RETRYABLE"

    if "GIT_LOCK_BUSY" in message:
        return "WRITER_BUSY"

    if (
        "CLAIM" in message
        and "BUSY" in message
    ):
        return "CLAIM_BUSY"

    if (
        "WRITER" in message
        and "BUSY" in message
    ):
        return "WRITER_BUSY"

    return "RECOVERY_REQUIRED"


def submit(
    job_spec: dict[str, Any],
    *,
    remote: str = "origin",
    queue_branch: str = "worker/requests",
) -> dict[str, Any]:

    try:
        template = validate_template(
            job_spec
        )

        from tools.mirror_sync.universal_job_bridge import (
            validate as validate_worker_job,
        )

        errors = validate_worker_job(
            template
        )

        if errors:
            return {
                "status": "INVALID_JOB",
                "errors": errors,
                "production_touched": False,
            }

    except Exception as exc:
        return {
            "status": "INVALID_JOB",
            "reason": (
                f"{type(exc).__name__}:{exc}"
            ),
            "production_touched": False,
        }

    job_id = str(
        template["job_id"]
    )

    try:
        draft = _atomic_submit_draft(
            template
        )
    except Exception as exc:
        return {
            "status": "RECOVERY_REQUIRED",
            "job_id": job_id,
            "reason": (
                f"{type(exc).__name__}:{exc}"
            ),
            "production_touched": False,
        }

    lifecycle = _submit_local_lifecycle(
        job_id
    )

    if lifecycle:
        return {
            "status": lifecycle,
            "job_id": job_id,
            "draft_path": str(draft),
            "production_touched": False,
        }

    if _submit_remote_exists(
        job_id,
        remote=remote,
        queue_branch=queue_branch,
    ):
        return {
            "status": "ALREADY_SUBMITTED",
            "job_id": job_id,
            "draft_path": str(draft),
            "production_touched": False,
        }

    try:
        from tools.mirror_sync.worker_requester_rbac import (
            authorize_requester,
        )

        authorization = authorize_requester(
            template["requester"]
        )

    except Exception as exc:
        return {
            "status": "REQUESTER_DENIED",
            "job_id": job_id,
            "reason": (
                f"{type(exc).__name__}:{exc}"
            ),
            "production_touched": False,
        }

    if (
        authorization.get("allowed")
        is not True
    ):
        return {
            "status": "REQUESTER_DENIED",
            "job_id": job_id,
            "reason": authorization.get(
                "reason"
            ),
            "production_touched": False,
        }

    convergence = _submit_convergence(
        remote=remote
    )

    if (
        convergence.get("converged")
        is not True
    ):
        return {
            "status": "WAITING_FOR_CONVERGENCE",
            "job_id": job_id,
            "draft_path": str(draft),
            "convergence": convergence,
            "production_touched": False,
        }

    plan = {
        "status": "READY_TO_PUBLISH",
        "job_id": job_id,
        "template": template,
    }

    try:
        publication = publish(
            plan,
            remote=remote,
            queue_branch=queue_branch,
        )

    except Exception as exc:
        return {
            "status": _submit_failure_status(
                exc
            ),
            "job_id": job_id,
            "draft_path": str(draft),
            "reason": (
                f"{type(exc).__name__}:{exc}"
            ),
            "production_touched": False,
        }

    publication_status = str(
        publication.get("status")
        or ""
    ).strip()

    if publication_status == "PUBLISHED":
        final = "SUBMITTED"
    elif publication_status == "EXISTS":
        final = "ALREADY_SUBMITTED"
    else:
        final = "RECOVERY_REQUIRED"

    return {
        "status": final,
        "job_id": job_id,
        "draft_path": str(draft),
        "publication": publication,
        "production_touched": False,
    }
